SELECT breakdown_id, tenant_id, cost_event_id, cost_type, cost_category, amount, currency, exchange_rate, amount_in_base_currency, remark, created_at
FROM fms_cost_breakdown WHERE tenant_id = #{tenantId} AND cost_event_id = #{costEventId}
ORDER BY created_at ASC

SELECT breakdown_id, tenant_id, cost_event_id, cost_type, cost_category, amount, currency, exchange_rate, amount_in_base_currency, remark, created_at
FROM fms_cost_breakdown WHERE tenant_id = #{tenantId} AND cost_type = #{costType}
ORDER BY created_at DESC

SELECT entry_id, tenant_id, account_code, account_name, type, amount, currency, reference_type, reference_id, remark, entry_date, created_at
FROM fms_journal_entry WHERE tenant_id = #{tenantId} AND reference_type = #{referenceType} AND reference_id = #{referenceId}
ORDER BY entry_date ASC

SELECT entry_id, tenant_id, account_code, account_name, type, amount, currency, reference_type, reference_id, remark, entry_date, created_at
FROM fms_journal_entry WHERE tenant_id = #{tenantId} AND account_code = #{accountCode}
ORDER BY entry_date DESC

