mapper.select:
SELECT result_id, tenant_id, rule_id, cost_event_id, target_dimension,
       target_id, allocated_amount, currency, exchange_rate,
       amount_in_base_currency, dimensions_json, allocated_at
FROM fms_cost_allocation_result
WHERE tenant_id = #{tenantId}
  AND target_dimension = #{targetDimension}
  AND target_id = #{targetId}
ORDER BY allocated_at ASC, result_id ASC

SELECT result_id, tenant_id, rule_id, cost_event_id, target_dimension,
       target_id, allocated_amount, currency, exchange_rate,
       amount_in_base_currency, dimensions_json, allocated_at
FROM fms_cost_allocation_result
WHERE tenant_id = #{tenantId}
  AND target_dimension = #{dimensionType}
  AND target_id = #{dimensionId}
ORDER BY allocated_at ASC, result_id ASC

